class Person:
    count = 0
    def __init__(self):
        self.count += 1
    def getCount(self):
        return self.count
class Student(Person):
    def change(self):
        self.count += 1
if __name__ == '__main__':
    s = Student()
    print(s.getCount())
    s.change()
    print(s.getCount())

class Person:
    def __init__(self, name, birth):
        self.name = name
        self.birth = birth
class Student(Person):
    def __init__(self, name, birth, gpa):
        Person.__init__(self, name, birth)
        self.gpa = gpa
    def display(self):
        print(f'{self.name} {self.birth} {self.gpa:.2f}')
if __name__ == '__main__':
    s = Student('28tech', '01/01/2022', 2.5)
    s.display()
